// --- Auth ---
// Token is read from ?token= on first load, moved to sessionStorage,
// then stripped from the URL to avoid exposure in history/logs.

function getQueryParams(): URLSearchParams {
  return new URLSearchParams(window.location.search)
}

const BEARER_PREFIX = 'Bearer '

const urlBearer = consumeUrlBearerToken()
if (urlBearer !== null) setStoredToken(urlBearer, { source: 'url' })

export function dashboardBearerToken(): string | null {
  return getStoredToken()
}

export function isLoopbackHostname(hostname: string): boolean {
  if (hostname === 'localhost' || hostname === '::1' || hostname === '[::1]') return true
  const octets = hostname.split('.')
  if (octets.length === 4 && octets.every(part => part !== '' && Number.isInteger(Number(part))
    && String(Number(part)) === part && Number(part) >= 0 && Number(part) <= 255)) return Number(octets[0]) === 127
  // URL.hostname canonicalizes IPv4-mapped IPv6 into two hexadecimal words.
  const host = hostname.startsWith('[') && hostname.endsWith(']') ? hostname.slice(1, -1) : hostname
  if (!host.startsWith('::ffff:')) return false
  const words = host.slice('::ffff:'.length).split(':')
  if (words.length !== 2 || words.some(word => word.length === 0 || word.length > 4)) return false
  const first = Number(`0x${words[0]}`)
  const second = Number(`0x${words[1]}`)
  return Number.isInteger(first) && first >= 0x7f00 && first <= 0x7fff
    && Number.isInteger(second) && second >= 0 && second <= 0xffff
}

export function isRemoteAccess(): boolean {
  return !isLoopbackHostname(window.location.hostname)
}

export function currentDashboardActor(): string {
  const meta = getStoredTokenMeta()
  const managedActor = getStoredToken() && meta?.source === 'dev'
    ? meta.actor
    : null
  if (managedActor) return managedActor
  return currentDashboardActorName()
}

/** Authority that sent a request; revisions distinguish token and actor ABA. */
export interface DashboardCredentialOwner {
  token: string | null
  tokenRevision: number
  actor: string
  actorRevision: number
  managed: boolean
  managedActorRevision: number
  managedAuthRevision: number
  managedRefusalObservation: number
}

export function captureDashboardCredentialOwner(): DashboardCredentialOwner {
  const token = dashboardBearerToken()
  return {
    token,
    tokenRevision: currentStoredTokenRevision(),
    actor: currentDashboardActor(),
    actorRevision: dashboardActorRevision.peek(),
    managed: token !== null && getStoredTokenMeta()?.source === 'dev',
    managedActorRevision: managedDashboardActorRevision.peek(),
    managedAuthRevision: managedDashboardAuthRevision.peek(),
    managedRefusalObservation: currentManagedRefusalObservation(),
  }
}

export function dashboardCredentialOwnerIsCurrent(owner: DashboardCredentialOwner): boolean {
  return owner.token === dashboardBearerToken()
    && owner.tokenRevision === currentStoredTokenRevision()
    && owner.actor === currentDashboardActor()
    && (owner.managed
      ? getStoredTokenMeta()?.source === 'dev'
        && owner.managedActorRevision === managedDashboardActorRevision.peek()
        && owner.managedAuthRevision === managedDashboardAuthRevision.peek()
        && owner.managedRefusalObservation === currentManagedRefusalObservation()
      : owner.actorRevision === dashboardActorRevision.peek())
}

type HeaderOptions = {
  includeActor?: boolean
  actorName?: string | null
}

export function authHeaders(options: HeaderOptions = {}): Record<string, string> {
  const headers: Record<string, string> = {}
  const token = dashboardBearerToken()
  const tokenMeta = getStoredTokenMeta()
  const resolvedImplicitActor = token && tokenMeta?.source !== 'dev'
    ? currentCanonicalDashboardActor()
    : currentDashboardActor()
  const agent = options.actorName !== undefined
    ? sanitizeDashboardActorName(options.actorName)
    : resolvedImplicitActor
  if (token) headers['Authorization'] = `${BEARER_PREFIX}${token}`
  if (options.includeActor !== false && agent) {
    headers['X-MASC-Agent'] = agent
  }
  return headers
}

export function jsonHeaders(): Record<string, string> {
  return {
    ...authHeaders(),
    'Content-Type': 'application/json',
  }
}

