/** [runtime_sync] on a refused config POST: the lane restart failed, or the
 *  write never reached the point of trying one. */
export type ConfigRuntimeSyncRefusal = 'failed' | 'not_attempted'

export class ApiRequestError extends Error {
  method: string
  path: string
  status?: number
  statusText?: string
  timeout: boolean
  detail?: string
  errorCode?: string
  authErrorCode?: string
  responseData?: unknown
  configApplied?: boolean
  configApplicationState?: 'indeterminate'
  runtimeSync?: ConfigRuntimeSyncRefusal
  authoritativeReloadRequired: boolean

  constructor(opts: {
    method: string
    path: string
    status?: number
    statusText?: string
    timeout?: boolean
    timeoutMs?: number
    detail?: string
    errorCode?: string
    authErrorCode?: string
    responseData?: unknown
    configApplied?: boolean
    configApplicationState?: 'indeterminate'
    runtimeSync?: ConfigRuntimeSyncRefusal
    authoritativeReloadRequired?: boolean
  }) {
    const method = opts.method.toUpperCase()
    const timeout = opts.timeout === true
    const detail = opts.detail?.trim()
    const message = timeout
      ? `${method} ${opts.path}: timeout after ${opts.timeoutMs ?? 0}ms`
      : detail
        ? `${method} ${opts.path}: ${detail}`
        : `${method} ${opts.path}: ${opts.status ?? 'unknown'} ${opts.statusText ?? ''}`.trim()
    super(message)
    this.name = 'ApiRequestError'
    this.method = method
    this.path = opts.path
    this.status = opts.status
    this.statusText = opts.statusText
    this.timeout = timeout
    this.detail = detail
    this.errorCode = opts.errorCode?.trim() || undefined
    this.authErrorCode = opts.authErrorCode?.trim() || undefined
    this.responseData = opts.responseData
    this.configApplied = opts.configApplied
    this.configApplicationState = opts.configApplicationState
    this.runtimeSync = opts.runtimeSync
    this.authoritativeReloadRequired = opts.authoritativeReloadRequired === true
  }
}

interface ApiErrorSummary {
  message: string
  status: number | null
  path: string | null
  timeout: boolean
}

export function extractApiError(err: unknown, fallbackMessage: string): ApiErrorSummary {
  if (err instanceof ApiRequestError) {
    return {
      message: err.message,
      status: err.status ?? null,
      path: err.path,
      timeout: err.timeout,
    }
  }
  if (err instanceof Error) {
    return { message: err.message, status: null, path: null, timeout: false }
  }
  return { message: fallbackMessage, status: null, path: null, timeout: false }
}

/** A 401 answered to a request that carried this Bearer token. */
export interface RejectedCredential {
  token: string
  authErrorCode: string | undefined
  httpStatus?: number
}

type RejectedCredentialListener = (rejection: RejectedCredential) => void

let rejectedCredentialListener: RejectedCredentialListener | null = null

/* Every credentialed request leaves through `credentialedFetch`, so one
   listener sees each 401 together with the token that request sent. The
   recovery policy lives in `dev-token.ts`, which imports this module; the app
   installs the listener at start so the import stays one-way. */
export function setRejectedCredentialListener(
  listener: RejectedCredentialListener | null,
): void {
  rejectedCredentialListener = listener
}

function sentBearerToken(headers: HeadersInit | undefined): string | null {
  if (!headers) return null
  let value: string | null = null
  if (headers instanceof Headers) {
    value = headers.get('Authorization')
  } else if (Array.isArray(headers)) {
    for (let i = 0; i < headers.length; i++) {
      const pair = headers[i]
      if (pair && pair[0].toLowerCase() === 'authorization') {
        value = pair[1]
        break
      }
    }
  } else {
    const rec = headers as Record<string, string | undefined>
    if (typeof rec.Authorization === 'string') {
      value = rec.Authorization
    } else if (typeof rec.authorization === 'string') {
      value = rec.authorization
    } else {
      for (const key in rec) {
        if (Object.prototype.hasOwnProperty.call(rec, key) && key.toLowerCase() === 'authorization') {
          value = rec[key] ?? null
          break
        }
      }
    }
  }
  if (value === null || !value.startsWith(BEARER_PREFIX)) return null
  const token = value.slice(BEARER_PREFIX.length).trim()
  return token === '' ? null : token
}

async function reportRejectedCredential(
  init: RequestInit,
  response: Response,
  owner: DashboardCredentialOwner,
  managed: boolean,
  managedRevision: number,
): Promise<void> {
  const listener = rejectedCredentialListener
  if (init.signal?.aborted || response.status !== 401 || listener === null) return
  const token = sentBearerToken(init.headers)
  if (token === null || token !== owner.token) return
  // A later 401 header makes an earlier shell validation stale even while
  // this response's body is still being read. The body decides whether the
  // token itself was refused; the observation alone does not block it.
  if (managed && owner.token === dashboardBearerToken()
    && owner.tokenRevision === currentStoredTokenRevision() && getStoredTokenMeta()?.source === 'dev'
    && owner.actor === currentDashboardActor() && managedRevision === managedDashboardActorRevision.peek()
    && owner.managedAuthRevision === managedDashboardAuthRevision.peek()) noteManagedCredentialRefusalObservation(owner.tokenRevision)
  // Cloned before this function first awaits, so the caller still owns the
  // original body.
  const info = await errorResponseInfoFromResponse(response.clone())
  if (init.signal?.aborted) return
  const managedStillCurrent = managed && owner.token === dashboardBearerToken()
    && owner.tokenRevision === currentStoredTokenRevision()
    && getStoredTokenMeta()?.source === 'dev' && owner.actor === currentDashboardActor()
    && managedRevision === managedDashboardActorRevision.peek()
    && owner.managedAuthRevision === managedDashboardAuthRevision.peek()
  if (managed ? !managedStillCurrent : !dashboardCredentialOwnerIsCurrent(owner)) return
  if (managed && (info.authErrorCode === 'invalid_token' || info.authErrorCode === 'token_expired')) {
    const expectedAuthRevision = managedDashboardAuthRevision.peek()
      + (managedDashboardRefusal.peek() === owner.tokenRevision ? 0 : 1)
    recordManagedCredentialRefusal(owner.tokenRevision)
    if (owner.token !== dashboardBearerToken() || owner.tokenRevision !== currentStoredTokenRevision()
      || getStoredTokenMeta()?.source !== 'dev' || owner.actor !== currentDashboardActor()
      || managedRevision !== managedDashboardActorRevision.peek()
      || managedDashboardAuthRevision.peek() !== expectedAuthRevision
      || rejectedCredentialListener !== listener) return
  }
  listener({ token, authErrorCode: info.authErrorCode, httpStatus: 401 })
}

type CredentialedRequestInit = RequestInit & { reportCredentialRefusal?: boolean }

async function credentialedFetch(path: string, init: CredentialedRequestInit): Promise<Response> {
  const { reportCredentialRefusal = true, ...requestInit } = init
  const owner = captureDashboardCredentialOwner()
  const managed = owner.token !== null && getStoredTokenMeta()?.source === 'dev'
  const managedRevision = managedDashboardActorRevision.peek()
  const credentialless = sentBearerToken(requestInit.headers) === null
    ? credentiallessRequest(requestInit.method, path, currentStoredTokenRevision())
    : null
  if (credentialless !== null) {
    const replayed = replayedRefusal(credentialless)
    if (replayed !== null) return replayed
  }
  const response = await fetch(path, requestInit)
  if (requestInit.signal?.aborted) throw new DOMException('Request cancelled', 'AbortError')
  //HIGH-RISK-UNREVIEWED: auth refusal path; when a credentialless 401 is kept moved off the caller's path.
  // The refusal is kept from a copy of the body while the caller already has
  // the 401 from its headers: a body that is slow or never ends must not hold
  // the refusal back from the screen. A request that starts after the body has
  // arrived is answered from the table; one that starts sooner is sent again
  // and gets the same 401.
  if (credentialless !== null && response.status === 401) {
    void noteRefusal(credentialless, response.clone(), requestInit.signal ?? undefined).catch(err => {
      if (!isAbortError(err)) console.warn('[dashboard-auth] credentialless refusal was not kept', err)
    })
  }
  if (requestInit.signal?.aborted) throw new DOMException('Request cancelled', 'AbortError')
  if (reportCredentialRefusal) void reportRejectedCredential(requestInit, response, owner, managed, managedRevision).catch(err => {
    console.warn('[dashboard-auth] rejected credential listener failed', err)
  })
  return response
}

/** A consumer keeps the deadline and caller abort connected through body read. */
export function fetchWithTimeout(path: string, init: CredentialedRequestInit, timeoutMs: number): Promise<Response>
export function fetchWithTimeout<T>(
  path: string,
  init: CredentialedRequestInit,
  timeoutMs: number,
  consume: (response: Response) => Promise<T>,
): Promise<T>
export async function fetchWithTimeout<T>(
  path: string,
  init: CredentialedRequestInit,
  timeoutMs: number,
  consume?: (response: Response) => Promise<T>,
): Promise<Response | T> {
  const controller = new AbortController()
  const upstreamSignal = init.signal
  const abortFromUpstream = () => controller.abort()
  const timer = setTimeout(() => controller.abort(), timeoutMs)

  if (upstreamSignal) {
    if (upstreamSignal.aborted) {
      controller.abort()
    } else {
      upstreamSignal.addEventListener('abort', abortFromUpstream, { once: true })
    }
  }

  try {
    const response = await credentialedFetch(path, {
      ...init,
      cache: init.cache ?? 'no-store',
      signal: controller.signal,
    })
    return consume ? await consume(response) : response
  } catch (err) {
    if (err instanceof ResponseHeaderRejected) {
      // The consumer deliberately refused this response before its body.
      // Abort the unread transport (and any cloned error reader) before
      // releasing the deadline, then preserve its original typed reason.
      controller.abort()
      throw err.reason
    }
    if (isAbortError(err)) {
      if (upstreamSignal?.aborted) {
        throw err
      }
      const method = typeof init.method === 'string' ? init.method.toUpperCase() : 'GET'
      throw new ApiRequestError({
        method,
        path,
        timeout: true,
        timeoutMs,
      })
    }
    throw err
  } finally {
    clearTimeout(timer)
    upstreamSignal?.removeEventListener('abort', abortFromUpstream)
  }
}

class ResponseHeaderRejected extends Error {
  constructor(readonly reason: unknown) { super('response rejected before body') }
}

/**
 * Control-plane operations complete when the server publishes their durable
 * outcome. A client-side wall-clock deadline can only hide that outcome while
 * the server continues the operation, so this boundary preserves only an
 * explicit caller-provided AbortSignal.
 */
export function fetchControlPlane(path: string, init: RequestInit): Promise<Response> {
  const method = typeof init.method === 'string' ? init.method.toUpperCase() : 'GET'
  if (method !== 'GET' && method !== 'HEAD') {
    bumpLegacyMutationGen(globalThis.fetch)
  }
  return credentialedFetch(path, {
    ...init,
    cache: init.cache ?? 'no-store',
  })
}

export async function fetchJsonWithTimeout(
  path: string,
  init: RequestInit,
  timeoutMs: number,
): Promise<{ response: Response; data: unknown | null }> {
  const controller = new AbortController()
  const upstreamSignal = init.signal
  let rejectBoundary: (reason: unknown) => void = () => undefined
  const boundary = new Promise<never>((_resolve, reject) => {
    rejectBoundary = reject
  })
  const abortFromUpstream = () => {
    controller.abort()
    rejectBoundary(upstreamSignal?.reason ?? new DOMException('Aborted', 'AbortError'))
  }
  const timer = setTimeout(() => {
    controller.abort()
    const method = typeof init.method === 'string' ? init.method.toUpperCase() : 'GET'
    rejectBoundary(new ApiRequestError({ method, path, timeout: true, timeoutMs }))
  }, timeoutMs)

  if (upstreamSignal) {
    if (upstreamSignal.aborted) {
      controller.abort()
    } else {
      upstreamSignal.addEventListener('abort', abortFromUpstream, { once: true })
    }
  }

  try {
    const request = (async () => {
      const response = await credentialedFetch(path, {
        ...init,
        cache: init.cache ?? 'no-store',
        signal: controller.signal,
      })
      return {
        response,
        data: response.ok ? await response.json() : null,
      }
    })()
    return await Promise.race([request, boundary])
  } catch (err) {
    if (isAbortError(err)) {
      if (upstreamSignal?.aborted) throw err
      const method = typeof init.method === 'string' ? init.method.toUpperCase() : 'GET'
      throw new ApiRequestError({ method, path, timeout: true, timeoutMs })
    }
    throw err
  } finally {
    clearTimeout(timer)
    upstreamSignal?.removeEventListener('abort', abortFromUpstream)
  }
}

const DASHBOARD_BOOTSTRAP_WARM_PATHS = new Set([
  '/api/v1/dashboard/shell',
  '/api/v1/dashboard/project-snapshot',
  '/api/v1/dashboard/execution',
  '/api/v1/dashboard/planning',
  '/api/v1/dashboard/briefing',
])

/**
 * Routes whose body the browser may hold and revalidate.
 *
 * Reads default to `no-store`, so a body reaches the browser's HTTP cache only
 * when its route is listed here. Two conditions gate membership, both measured
 * against a running server rather than assumed:
 *
 *   1. The body repeats byte-identically across reads. A route whose body
 *      changes on every read can never answer 304, so listing it would buy a
 *      digest computation and nothing else. `/dashboard/bootstrap` and
 *      `/activity/events` fail this and are absent.
 *   2. The body carries no secret projection. `/keepers/composite` embeds
 *      `secret_projection` -- environment variable names and host paths, no
 *      values -- and listing a route is precisely what would put those on
 *      disk, so it stays `no-store` despite repeating byte-identically.
 * Baseline measured 2026-08-13 against a live server: initial routes carried
 * 1,741,479 of the 2,132,911 bytes one refresh cycle transfers (81.6%).
 * Expanded in 2026-09 to cover execution, config, keeper-memory-health, tasks history,
 * workspace, briefing, planning, and tool-metrics where server-side
 * weak ETags and 304 fast-paths eliminate repetitive JSON transfer and deserialization.
 * Condition 2 costs 49,743 of those bytes (2.3%); condition 1 excludes dynamic
 * non-repeatable routes that no caching strategy could recover.
 *
 * Listing a route cannot serve a stale body: `no-cache` stores the response but
 * revalidates before every use, so the server's ETag decides what the client
 * sees, not a client-side freshness window.
 */
const BROWSER_REVALIDATED_PATHS = new Set([
  '/api/v1/dashboard/scheduled-automation',
  '/api/v1/dashboard/telemetry',
  '/api/v1/dashboard/tool-quality',
  '/api/v1/dashboard/board',
  '/api/v1/board',
  '/api/v1/dashboard/harness-health',
  '/api/v1/agent-activity',
  '/api/v1/dashboard/goals',
  '/api/v1/dashboard/gate',
  '/api/v1/dashboard/execution',
  '/api/v1/dashboard/config',
  '/api/v1/dashboard/keeper-memory-health',
  '/api/v1/dashboard/tasks/history',
  '/api/v1/dashboard/workspace',
  '/api/v1/dashboard/briefing',
  '/api/v1/dashboard/planning',
  '/api/v1/tool-metrics',
])

/**
 * Eligibility belongs to the route, not to one request's parameters:
 * `/dashboard/telemetry?window=1h` is the same route as `/dashboard/telemetry`,
 * and several callers build paths that way. Matching the path as given would
 * silently miss every parameterised caller.
 *
 * Matching by prefix would fail in the other direction -- it would capture
 * `/dashboard/telemetry/summary`, a distinct route that was never measured. So
 * the query is split off and what remains is matched exactly.
 *
 * A route absent from the set gets `no-store`, which is what an unrecognised
 * path should get: the conservative answer, not the convenient one.
 */
export function readCacheMode(path: string): RequestCache {
  const queryStart = path.indexOf('?')
  const route = queryStart === -1 ? path : path.slice(0, queryStart)
  return BROWSER_REVALIDATED_PATHS.has(route) ? 'no-cache' : 'no-store'
}

import { isRecord } from '../lib/type-guards'

interface ErrorResponseInfo {
  detail?: string
  errorCode?: string
  authErrorCode?: string
  responseData?: unknown
  configApplied?: boolean
  configApplicationState?: 'indeterminate'
  runtimeSync?: ConfigRuntimeSyncRefusal
  authoritativeReloadRequired?: boolean
}

async function errorResponseInfoFromResponse(res: Response, preserveAbort = false, preserveReadFailure = false): Promise<ErrorResponseInfo> {
  let rawText = ''
  try {
    rawText = (await res.text()).trim()
  } catch (error) {
    if (preserveReadFailure || (preserveAbort && isAbortError(error))) throw error
    return {}
  }
  if (!rawText) return {}
  try {
    const parsed = JSON.parse(rawText) as unknown
    if (isRecord(parsed)) {
      const jsonRpcError = isRecord(parsed.error) ? parsed.error : null
      const jsonRpcErrorData = jsonRpcError && isRecord(jsonRpcError.data)
        ? jsonRpcError.data
        : null
      const errorDetail = typeof parsed.error === 'string' ? parsed.error.trim() : ''
      const structuredErrorCode = typeof jsonRpcError?.code === 'string'
        ? jsonRpcError.code.trim()
        : ''
      const structuredErrorDetail = typeof jsonRpcError?.detail === 'string'
        ? jsonRpcError.detail.trim()
        : ''
      const topLevelAuthErrorCode = typeof parsed.auth_error_code === 'string'
        ? parsed.auth_error_code.trim()
        : ''
      const jsonRpcAuthErrorCode = typeof jsonRpcErrorData?.auth_error_code === 'string'
        ? jsonRpcErrorData.auth_error_code.trim()
        : ''
      const authErrorCode = topLevelAuthErrorCode || jsonRpcAuthErrorCode
      // Server refusals (Server_refusal.json) carry their machine code in a
      // top-level `code` field, next to a human `error` string.
      const topLevelErrorCode = typeof parsed.code === 'string' ? parsed.code.trim() : ''
      const errorCode =
        authErrorCode
        || (typeof parsed.error_code === 'string' ? parsed.error_code.trim() : '')
        || topLevelErrorCode
        || structuredErrorCode
        || (typeof parsed.status === 'string' ? parsed.status.trim() : '')
        || errorDetail
      const topLevelMessage = typeof parsed.message === 'string' ? parsed.message.trim() : ''
      const jsonRpcMessage = typeof jsonRpcError?.message === 'string'
        ? jsonRpcError.message.trim()
        : ''
      const message = topLevelMessage || jsonRpcMessage || structuredErrorDetail
      // The state key is the discriminator; counting fields would flip the
      // verdict the moment the server adds a detail field, exactly when the
      // operator most needs to know the write outcome is indeterminate.
      const configApplicationState = isRecord(parsed.config_application)
        && parsed.config_application.state === 'indeterminate'
        ? 'indeterminate' as const
        : undefined
      if (message || errorDetail || errorCode) {
        return {
          detail: message || errorDetail || errorCode || undefined,
          errorCode: errorCode || undefined,
          authErrorCode: authErrorCode || undefined,
          responseData: parsed,
          configApplied:
            typeof parsed.config_applied === 'boolean'
              ? parsed.config_applied
              : undefined,
          configApplicationState,
          runtimeSync: parsed.runtime_sync === 'failed'
            || parsed.runtime_sync === 'not_attempted'
            ? parsed.runtime_sync
            : undefined,
          authoritativeReloadRequired:
            parsed.authoritative_reload_required === true,
        }
      }
      // Some conflict responses carry a receipt without an error/message key.
      // Preserve the structured body for operation-specific reconciliation.
      return { detail: rawText, responseData: parsed }
    }
  } catch {
    // Fall through to plain-text body.
  }
  return { detail: rawText }
}

export async function apiRequestErrorFromResponse(
  method: string,
  path: string,
  res: Response,
  preserveAbort = false,
  preserveReadFailure = false,
): Promise<ApiRequestError> {
  const info = await errorResponseInfoFromResponse(res, preserveAbort, preserveReadFailure)
  return new ApiRequestError({
    method,
    path,
    status: res.status,
    statusText: res.statusText,
    detail: info.detail,
    errorCode: info.errorCode,
    authErrorCode: info.authErrorCode,
    responseData: info.responseData,
    configApplied: info.configApplied,
    configApplicationState: info.configApplicationState,
    runtimeSync: info.runtimeSync,
    authoritativeReloadRequired: info.authoritativeReloadRequired,
  })
}

function isBlankText(s: string): boolean {
  const len = s.length
  if (len === 0) return true
  const c0 = s.charCodeAt(0)
  if (c0 > 32 && c0 < 127) return false
  return s.trim() === ''
}

async function parseJsonResponse<T>(
  method: string,
  path: string,
  res: Response,
  preserveAbort = false,
  rejectDuplicateMembers = false,
): Promise<T> {
  let rawText = ''
  try {
    rawText = await res.text()
  } catch (error) {
    if (preserveAbort && isAbortError(error)) throw error
    throw new ApiRequestError({
      method,
      path,
      status: res.status,
      statusText: res.statusText,
      detail: 'failed to read response body',
    })
  }

  if (isBlankText(rawText)) {
    throw new ApiRequestError({
      method,
      path,
      status: res.status,
      statusText: res.statusText,
      detail: 'empty JSON response',
    })
  }

  try {
    return (rejectDuplicateMembers ? parseUniqueJson(rawText) : JSON.parse(rawText)) as T
  } catch {
    throw new ApiRequestError({
      method,
      path,
      status: res.status,
      statusText: res.statusText,
      detail: 'invalid JSON response',
    })
  }
}

// The server answers a warm-up read with `{"status":"initializing"}` on
// /api/v1/dashboard/* paths and `{"error":"not initialized"}` elsewhere
// (lib/server/server_auth.ml not_initialized_response). Both mean the same
// thing: no state yet, try again.
function isNotInitializedEnvelope(raw: unknown): boolean {
  if (!isRecord(raw)) return false
  if (typeof raw.status === 'string' && raw.status === 'initializing') return true
  return typeof raw.error === 'string' && raw.error.trim().toLowerCase() === 'not initialized'
}

function bootstrapStatusEnvelope(generatedAt: string): Record<string, unknown> {
  return {
    project: 'initializing',
    generated_at: generatedAt,
  }
}

function bootstrapInitializingPayload(path: string): unknown | null {
  const generatedAt = new Date().toISOString()
  switch (path) {
    case '/api/v1/dashboard/shell':
      return {
        generated_at: generatedAt,
        status: bootstrapStatusEnvelope(generatedAt),
        counts: { agents: 0, tasks: 0, keepers: 0 },
        providers: {},
        auth: null,
        config_resolution: null,
        runtime_resolution: null,
      }
    case '/api/v1/dashboard/project-snapshot':
      return {
        status: 'initializing',
        generated_at: generatedAt,
        message: 'Dashboard bootstrap is still warming up.',
      }
    case '/api/v1/dashboard/execution':
      return {
        generated_at: generatedAt,
        status: bootstrapStatusEnvelope(generatedAt),
        summary: {},
        execution_queue: [],
        operation_briefs: [],
        worker_support_briefs: [],
        continuity_briefs: [],
        offline_worker_briefs: [],
        agents: [],
        tasks: [],
        messages: [],
        keepers: [],
      }
    case '/api/v1/dashboard/planning':
      return {
        generated_at: generatedAt,
        goals: [],
        rollup: {},
        task_backlog: {
          todo: 0,
          claimed: 0,
          in_progress: 0,
          awaiting_verification: 0,
          done: 0,
          cancelled: 0,
        },
      }
    case '/api/v1/dashboard/briefing':
      return {
        generated_at: generatedAt,
        summary: {
          workspace_health: 'initializing',
        },
        incidents: [],
        recommended_actions: [],
        command_focus: {},
        operator_targets: { keepers: [], available_actions: [] },
        attention_queue: [],
        sessions: [],
        agent_briefs: [],
        keeper_briefs: [],
        internal_signals: [],
      }
    default:
      return null
  }
}

async function bootstrapWarmPayload(path: string, res: Response): Promise<unknown | null> {
  if (!DASHBOARD_BOOTSTRAP_WARM_PATHS.has(path)) return null
  if (res.status < 500) return null
  let rawText = ''
  try {
    rawText = await res.text()
  } catch {
    return null
  }
  if (rawText.trim() === '') return null
  try {
    const parsed = JSON.parse(rawText) as unknown
    if (!isNotInitializedEnvelope(parsed)) return null
    return bootstrapInitializingPayload(path)
  } catch {
    return null
  }
}

export function defaultBoardVoter(): string {
  const params = getQueryParams()
  return sanitizeDashboardActorName(params.get('agent'))
    || sanitizeDashboardActorName(params.get('agent_name'))
    || 'dashboard-user'
}

// --- Generic fetcher ---

/**
 * Minimal request contract: the caller may pass an AbortSignal to cancel
 * the underlying fetch. Several api/* modules (dashboard, dashboard-hot,
 * transport-health) had defined this byte-for-byte locally; lifting it
 * here makes the abort contract single-sourced and lets callers compose
 * extensions like `AbortableRequestOptions & { light?: boolean }` against
 * a stable base.
 */
export type AbortableRequestOptions = {
  signal?: AbortSignal
}

export type GetOptions = AbortableRequestOptions & {
  timeoutMs?: number
  includeActorHeader?: boolean
  extraHeaders?: Record<string, string>
  /** Keep the GET deadline and caller abort connected through JSON consumption; defaults to true. */
  consumeWithinTimeout?: boolean
  reportCredentialRefusal?: boolean
}

// --- In-flight GET coalescing (per globalThis.fetch & mutation generation) ---

interface SharedLegacyGetFlight {
  readonly controller: AbortController
  refCount: number
  readonly promise: Promise<{ readonly data: unknown; readonly headers: Headers }>
}

const inflightLegacyGetsByFetch = new WeakMap<typeof fetch, Map<string, SharedLegacyGetFlight>>()
const legacyMutationGenByFetch = new WeakMap<typeof fetch, number>()

function currentLegacyMutationGen(fetchImpl: typeof fetch): number {
  return legacyMutationGenByFetch.get(fetchImpl) ?? 0
}

function bumpLegacyMutationGen(fetchImpl: typeof fetch): void {
  legacyMutationGenByFetch.set(fetchImpl, currentLegacyMutationGen(fetchImpl) + 1)
  inflightLegacyGetsByFetch.get(fetchImpl)?.clear()
}

function legacyInflightMapFor(fetchImpl: typeof fetch): Map<string, SharedLegacyGetFlight> {
  let map = inflightLegacyGetsByFetch.get(fetchImpl)
  if (!map) {
    map = new Map()
    inflightLegacyGetsByFetch.set(fetchImpl, map)
  }
  return map
}

function sortedHeaderSig(headers: Record<string, string>): string {
  const keys = Object.keys(headers)
  if (keys.length === 0) return ''
  keys.sort()
  let out = ''
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i]!
    out += `${k.toLowerCase()}=${headers[k]!}\0`
  }
  return out
}

async function coalescedLegacyGet<T>(
  path: string,
  headers: Record<string, string>,
  cache: RequestCache,
  anonymous: boolean,
  timeoutMs: number,
  upstreamSignal: AbortSignal | undefined,
  reportCredentialRefusal: boolean | undefined,
  preserveErrorBodyFailure: boolean | undefined,
  rejectDuplicateJsonMembers: boolean | undefined,
): Promise<{ readonly data: T; readonly headers: Headers }> {
  const fetchImpl = globalThis.fetch
  const flightGen = currentLegacyMutationGen(fetchImpl)
  const owner = captureDashboardCredentialOwner()
  const flightKey =
    `${flightGen}\0${anonymous ? 1 : 0}\0${cache}\0${path}\0${sortedHeaderSig(headers)}`
    + `\0${owner.tokenRevision}:${owner.actorRevision}:${owner.managed ? 1 : 0}:${owner.managedActorRevision}:${owner.managedAuthRevision}:${owner.managedRefusalObservation}`
    + `\0${reportCredentialRefusal === false ? 0 : 1}:${preserveErrorBodyFailure === true ? 1 : 0}:${rejectDuplicateJsonMembers === true ? 1 : 0}`

  const flights = legacyInflightMapFor(fetchImpl)
  let flight = flights.get(flightKey)
  if (flight && flight.controller.signal.aborted) {
    flights.delete(flightKey)
    flight = undefined
  }
  if (!flight) {
    const flightController = new AbortController()
    const requestInit: CredentialedRequestInit = {
      headers,
      ...(anonymous ? { credentials: 'omit' as const } : {}),
      cache,
      signal: flightController.signal,
      reportCredentialRefusal,
    }
    const promise = (async (): Promise<{ readonly data: unknown; readonly headers: Headers }> => {
      try {
        const res = await credentialedFetch(path, requestInit)
        if (!res.ok) {
          if (flights.get(flightKey)?.controller === flightController) {
            flights.delete(flightKey)
          }
          const warmPayload = await bootstrapWarmPayload(path, res.clone())
          if (warmPayload !== null) return { data: warmPayload, headers: new Headers() }
          throw await apiRequestErrorFromResponse('GET', path, res, true, preserveErrorBodyFailure)
        }
        const data = await parseJsonResponse<unknown>('GET', path, res, true, rejectDuplicateJsonMembers)
        if (DASHBOARD_BOOTSTRAP_WARM_PATHS.has(path) && isNotInitializedEnvelope(data)) {
          const payload = bootstrapInitializingPayload(path)
          if (payload !== null) return { data: payload, headers: new Headers() }
        }
        return { data, headers: res.headers }
      } finally {
        if (flights.get(flightKey)?.controller === flightController) {
          flights.delete(flightKey)
        }
      }
    })()
    // Prevent unhandled rejection when all callers detach early and transport aborts.
    promise.catch(() => {})
    flight = { controller: flightController, refCount: 0, promise }
    flights.set(flightKey, flight)
  }

  flight.refCount += 1
  let detached = false
  let timer: ReturnType<typeof setTimeout> | null = null
  let rejectCaller: ((reason: unknown) => void) | null = null

  const detachAndMaybeAbort = (abortTransport: boolean): void => {
    if (detached) return
    detached = true
    flight.refCount -= 1
    if (abortTransport && flight.refCount <= 0) {
      if (flights.get(flightKey) === flight) {
        flights.delete(flightKey)
      }
      flight.controller.abort()
    }
  }

  const abortFromUpstream = () => {
    detachAndMaybeAbort(true)
    rejectCaller?.(new DOMException('Request cancelled', 'AbortError'))
  }

  const callerRace = new Promise<never>((_resolve, reject) => {
    rejectCaller = reject
    timer = setTimeout(() => {
      detachAndMaybeAbort(true)
      reject(new ApiRequestError({ method: 'GET', path, timeout: true, timeoutMs }))
    }, timeoutMs)
    if (upstreamSignal) {
      upstreamSignal.addEventListener('abort', abortFromUpstream, { once: true })
    }
  })

  try {
    const result = await Promise.race([flight.promise, callerRace])
    return result as { readonly data: T; readonly headers: Headers }
  } catch (err) {
    if (isAbortError(err)) {
      if (upstreamSignal?.aborted) throw err
      throw new ApiRequestError({ method: 'GET', path, timeout: true, timeoutMs })
    }
    throw err
  } finally {
    if (timer !== null) clearTimeout(timer)
    upstreamSignal?.removeEventListener('abort', abortFromUpstream)
    detachAndMaybeAbort(false)
  }
}

async function getRequest<T>(path: string, opts: GetOptions, anonymous: boolean): Promise<T> {
  const consumeWithinTimeout = opts.consumeWithinTimeout ?? true
  const headers: Record<string, string> = anonymous
    ? {}
    : { ...authHeaders({ includeActor: opts.includeActorHeader }), ...opts.extraHeaders }
  const cache = readCacheMode(path)
  const timeoutMs = opts.timeoutMs ?? DEFAULT_GET_TIMEOUT_MS

  // Skip in-flight coalescing for credentialless non-anonymous GETs so
  // concurrent requests honor the credentialless 401 refusal contract (#54963).
  if (consumeWithinTimeout && !opts.signal?.aborted && (anonymous || sentBearerToken(headers) !== null)) {
    const result = await coalescedLegacyGet<T>(
      path,
      headers,
      cache,
      anonymous,
      timeoutMs,
      opts.signal,
      opts.reportCredentialRefusal,
      undefined,
      undefined,
    )
    return result.data
  }

  const consume = async (res: Response): Promise<T> => {
    if (!res.ok) {
      const warmPayload = await bootstrapWarmPayload(path, res.clone())
      if (warmPayload !== null) return warmPayload as T
      throw await apiRequestErrorFromResponse('GET', path, res, consumeWithinTimeout)
    }
    const data = await parseJsonResponse<T>('GET', path, res, consumeWithinTimeout)
    if (DASHBOARD_BOOTSTRAP_WARM_PATHS.has(path) && isNotInitializedEnvelope(data)) {
      const payload = bootstrapInitializingPayload(path)
      if (payload !== null) return payload as T
    }
    return data
  }
  const init = {
    headers,
    ...(anonymous ? { credentials: 'omit' as const } : {}),
    cache,
    signal: opts.signal,
    reportCredentialRefusal: opts.reportCredentialRefusal,
  }
  if (consumeWithinTimeout) return fetchWithTimeout(path, init, timeoutMs, consume)
  return consume(await fetchWithTimeout(path, init, timeoutMs))
}

export async function get<T>(path: string, opts: GetOptions = {}): Promise<T> {
  return getRequest<T>(path, opts, false)
}

// Public capability reads must not inherit a stored token, actor or cookies.
export async function getPublic<T>(path: string, opts: AbortableRequestOptions = {}): Promise<T> {
  return getRequest<T>(path, { ...opts, consumeWithinTimeout: true }, true)
}

// Same wire shape as [get<T>] but exposes selected response headers
// alongside the parsed body. Use when a route returns metadata via
// header (e.g. [X-Workspace-Source]) so callers can read it without
// parsing the JSON body or breaking the existing return type.
//
// On bootstrap-warm fallback the returned [headers] is empty: warm
// payloads are synthesized locally and have no upstream response.
export async function getWithResponse<T>(
  path: string,
  opts: GetOptions & {
    beforeResponseBody?: (response: Pick<Response, 'status' | 'statusText' | 'ok' | 'headers'>) => void
    preserveErrorBodyFailure?: boolean
    reportCredentialRefusal?: boolean
    rejectDuplicateJsonMembers?: boolean
  } = {},
): Promise<{ readonly data: T; readonly headers: Headers }> {
  const consumeWithinTimeout = opts.consumeWithinTimeout ?? true
  const headers: Record<string, string> = {
    ...authHeaders({ includeActor: opts.includeActorHeader }),
    ...opts.extraHeaders,
  }
  const cache = readCacheMode(path)
  const timeoutMs = opts.timeoutMs ?? DEFAULT_GET_TIMEOUT_MS

  if (
    consumeWithinTimeout
    && !opts.beforeResponseBody
    && !opts.signal?.aborted
    && sentBearerToken(headers) !== null
  ) {
    return coalescedLegacyGet<T>(
      path,
      headers,
      cache,
      false,
      timeoutMs,
      opts.signal,
      opts.reportCredentialRefusal,
      opts.preserveErrorBodyFailure,
      opts.rejectDuplicateJsonMembers,
    )
  }

  const consume = async (res: Response): Promise<{ readonly data: T; readonly headers: Headers }> => {
    if (opts.beforeResponseBody) {
      try { opts.beforeResponseBody(res) }
      catch (reason) {
        if (consumeWithinTimeout) throw new ResponseHeaderRejected(reason)
        throw reason
      }
    }
    if (!res.ok) {
      const warmPayload = await bootstrapWarmPayload(path, res.clone())
      if (warmPayload !== null) return { data: warmPayload as T, headers: new Headers() }
      throw await apiRequestErrorFromResponse('GET', path, res, consumeWithinTimeout, opts.preserveErrorBodyFailure)
    }
    const data = await parseJsonResponse<T>('GET', path, res, consumeWithinTimeout, opts.rejectDuplicateJsonMembers)
    if (DASHBOARD_BOOTSTRAP_WARM_PATHS.has(path) && isNotInitializedEnvelope(data)) {
      const payload = bootstrapInitializingPayload(path)
      if (payload !== null) return { data: payload as T, headers: new Headers() }
    }
    return { data, headers: res.headers }
  }
  const init = {
    headers,
    cache,
    signal: opts.signal,
    reportCredentialRefusal: opts.reportCredentialRefusal,
  }
  if (consumeWithinTimeout) return fetchWithTimeout(path, init, timeoutMs, consume)
  return consume(await fetchWithTimeout(path, init, timeoutMs))
}

export function runRequest<T>(_operation: string, run: () => Promise<T>): Promise<T> {
  return run()
}

export async function post<T>(
  path: string,
  body: unknown,
  extraHeaders?: Record<string, string>,
  timeoutMs = DEFAULT_POST_TIMEOUT_MS,
  signal?: AbortSignal,
  consumeWithinTimeout = false,
  opts: { reportCredentialRefusal?: boolean; preserveErrorBodyFailure?: boolean;
    beforeResponseBody?: (response: Pick<Response, 'status' | 'statusText' | 'ok' | 'headers'>) => void } = {},
): Promise<T> {
  const fetchImpl = globalThis.fetch
  const init = {
    method: 'POST',
    headers: {
      ...jsonHeaders(),
      ...(extraHeaders ?? {}),
    },
    body: JSON.stringify(body),
    reportCredentialRefusal: opts.reportCredentialRefusal,
    ...(signal ? { signal } : {}),
  }
  const consumeBody = Boolean(signal) || consumeWithinTimeout
  const consume = async (res: Response): Promise<T> => {
    if (opts.beforeResponseBody) {
      try { opts.beforeResponseBody(res) }
      catch (reason) {
        if (consumeBody) throw new ResponseHeaderRejected(reason)
        throw reason
      }
    }
    if (!res.ok) throw await apiRequestErrorFromResponse('POST', path, res, consumeBody, opts.preserveErrorBodyFailure)
    bumpLegacyMutationGen(fetchImpl)
    return parseJsonResponse<T>('POST', path, res, consumeBody)
  }
  if (consumeBody) return fetchWithTimeout(path, init, timeoutMs, consume)
  return consume(await fetchWithTimeout(path, init, timeoutMs))
}

export async function postControlPlane<T>(
  path: string,
  body: unknown,
  extraHeaders?: Record<string, string>,
  opts: AbortableRequestOptions = {},
): Promise<T> {
  const fetchImpl = globalThis.fetch
  const res = await fetchControlPlane(path, {
    method: 'POST',
    headers: {
      ...jsonHeaders(),
      ...(extraHeaders ?? {}),
    },
    body: JSON.stringify(body),
    signal: opts.signal,
  })
  if (!res.ok) {
    throw await apiRequestErrorFromResponse('POST', path, res)
  }
  bumpLegacyMutationGen(fetchImpl)
  return parseJsonResponse<T>('POST', path, res)
}

export async function patch<T>(
  path: string,
  body: unknown,
  extraHeaders?: Record<string, string>,
  timeoutMs = DEFAULT_POST_TIMEOUT_MS,
): Promise<T> {
  const fetchImpl = globalThis.fetch
  // Backend uses POST with PATCH semantics (OCaml server only routes POST)
  const res = await fetchWithTimeout(path, {
    method: 'POST',
    headers: {
      ...jsonHeaders(),
      ...(extraHeaders ?? {}),
    },
    body: JSON.stringify(body),
  }, timeoutMs)
  if (!res.ok) {
    throw await apiRequestErrorFromResponse('PATCH', path, res)
  }
  bumpLegacyMutationGen(fetchImpl)
  return parseJsonResponse<T>('PATCH', path, res)
}

